require __DIR__.'/../bootstrap.php'; require_admin(); ensure_cms_schema();
$kind=(($_GET['type']??'category')==='tag')?'tag':'category';$isCat=$kind==='category';$title=$isCat?'Categories':'Tags';$table=$isCat?'cms_categories':'cms_tags';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=(string)post('action','save');if($action==='save'){ $id=(int)post('id',0);$name=trim((string)post('name',''));if($name===''){flash('error','Name is required.');redirect('/admin/'.($isCat?'categories':'tags').'/');}$slug=cms_slug((string)post('slug',$name));$desc=(string)post('description','');if($isCat){$parent=(int)post('parent_id',0);$color=preg_match('/^#[0-9a-fA-F]{6}$/',(string)post('archive_color',''))?post('archive_color'):null;if($id){db()->prepare('UPDATE cms_categories SET name=?,slug=?,parent_id=?,description=?,archive_color=?,updated_at=NOW() WHERE id=?')->execute([$name,$slug,$parent?:null,$desc,$color,$id]);}else{db()->prepare('INSERT INTO cms_categories(name,slug,parent_id,description,archive_color,created_at,updated_at) VALUES(?,?,?,?,?,NOW(),NOW())')->execute([$name,$slug,$parent?:null,$desc,$color]);}}else{if($id){db()->prepare('UPDATE cms_tags SET name=?,slug=?,description=?,updated_at=NOW() WHERE id=?')->execute([$name,$slug,$desc,$id]);}else{db()->prepare('INSERT INTO cms_tags(name,slug,description,created_at,updated_at) VALUES(?,?,?,NOW(),NOW())')->execute([$name,$slug,$desc]);}}flash('success',$title.' saved.');redirect('/admin/'.($isCat?'categories':'tags').'/');}if($action==='delete'){$id=(int)post('id');if($id)db()->prepare("DELETE FROM {$table} WHERE id=?")->execute([$id]);flash('success','Item deleted.');redirect('/admin/'.($isCat?'categories':'tags').'/');}if($action==='convert'){ $id=(int)post('id');if($id){if($isCat){$s=db()->prepare('SELECT * FROM cms_categories WHERE id=?');$s->execute([$id]);$x=$s->fetch();if($x){$tagSlug=cms_slug($x['slug']);$st=db()->prepare('SELECT id FROM cms_tags WHERE slug=?');$st->execute([$tagSlug]);$tid=$st->fetchColumn();if(!$tid){db()->prepare('INSERT INTO cms_tags(name,slug,description,created_at,updated_at) VALUES(?,?,?,NOW(),NOW())')->execute([$x['name'],$tagSlug,$x['description']]);$tid=db()->lastInsertId();}$posts=db()->prepare('SELECT post_id FROM cms_post_categories WHERE category_id=?');$posts->execute([$id]);$ins=db()->prepare('INSERT IGNORE INTO cms_post_tags(post_id,tag_id) VALUES(?,?)');foreach($posts as $p)$ins->execute([$p['post_id'],$tid]);}}else{$s=db()->prepare('SELECT * FROM cms_tags WHERE id=?');$s->execute([$id]);$x=$s->fetch();if($x){$slug=cms_slug($x['slug']);$st=db()->prepare('SELECT id FROM cms_categories WHERE slug=?');$st->execute([$slug]);$cid=$st->fetchColumn();if(!$cid){db()->prepare('INSERT INTO cms_categories(name,slug,description,created_at,updated_at) VALUES(?,?,?,NOW(),NOW())')->execute([$x['name'],$slug,$x['description']]);$cid=db()->lastInsertId();}$posts=db()->prepare('SELECT post_id FROM cms_post_tags WHERE tag_id=?');$posts->execute([$id]);$ins=db()->prepare('INSERT IGNORE INTO cms_post_categories(post_id,category_id) VALUES(?,?)');foreach($posts as $p)$ins->execute([$p['post_id'],$cid]);}}}flash('success','Conversion completed.');redirect('/admin/'.($isCat?'categories':'tags').'/');}}
$search=trim((string)getv('q',''));$where=$search!==''?'WHERE name LIKE ?':'';$s=$pdo=db();$st=$pdo->prepare("SELECT * FROM {$table} {$where} ORDER BY name");$st->execute($search!==''?["%$search%"]:[]);$items=$st->fetchAll();$editId=(int)getv('edit',0);$edit=null;if($editId){$x=$pdo->prepare("SELECT * FROM {$table} WHERE id=?");$x->execute([$editId]);$edit=$x->fetch();}$parents=$isCat?$pdo->query('SELECT id,name FROM cms_categories ORDER BY name')->fetchAll():[];$title=$title.' · CMS';require __DIR__.'/../includes/header.php';
?>
<div class="page-head"><div><span class="eyebrow">Content Management</span><h1><?=$title?></h1><p>Organize content with searchable taxonomy and one-click conversion.</p></div><div class="actions"><a class="btn secondary" href="/admin/<?=$isCat?'tags':'categories'?>/">Switch to <?=$isCat?'Tags':'Categories'?></a></div></div><div class="grid2 cms-tax-grid"><section class="card"><h2>Add <?=$isCat?'Category':'Tag'?></h2><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e($edit['id']??0)?>"><label>Name<input required name="name" value="<?=e($edit['name']??'')?>"></label><label>Slug<input name="slug" value="<?=e($edit['slug']??'')?>"></label><?php if($isCat):?><label>Parent<select name="parent_id"><option value="0">None</option><?php foreach($parents as $p): if((int)($edit['id']??0)===(int)$p['id'])continue;?><option value="<?=$p['id']?>" <?=((int)($edit['parent_id']??0)===$p['id'])?'selected':''?>><?=e($p['name'])?></option><?php endforeach;?></select></label><label>Archive color<input type="color" name="archive_color" value="<?=e($edit['archive_color']??'#2563eb')?>"></label><?php endif;?><label>Description<textarea name="description" rows="6"><?=e($edit['description']??'')?></textarea></label><button class="btn" type="submit">Save <?=$isCat?'Category':'Tag'?></button><?php if($edit):?><a class="btn secondary" href="/admin/<?=$isCat?'categories':'tags'?>/">Cancel</a><?php endif;?></form></section><section class="card"><div class="page-head"><div><h2>Manage <?=$title?></h2></div><form class="cms-search" method="get"><input type="hidden" name="type" value="<?=$kind?>"><input name="q" value="<?=e($search)?>" placeholder="Search…"><button class="btn small">Search</button></form></div><div class="table-wrap"><table class="cms-table"><thead><tr><th>Name</th><th>Slug</th><th>Description</th><th>Count</th><th>Actions</th></tr></thead><tbody><?php foreach($items as $x):$cnt=$isCat?db()->prepare('SELECT COUNT(*) FROM cms_post_categories WHERE category_id=?'):db()->prepare('SELECT COUNT(*) FROM cms_post_tags WHERE tag_id=?');$cnt->execute([$x['id']]);$n=(int)$cnt->fetchColumn();?><tr><td><strong><?=e($x['name'])?></strong></td><td><?=e($x['slug'])?></td><td><?=e(mb_strimwidth((string)($x['description']??''),0,70,'…'))?></td><td><a href="/admin/posts/?<?= $isCat?'category':'tag'?>=<?=$x['id']?>"><?=$n?></a></td><td><div class="actions"><a class="btn small secondary" href="?type=<?=$kind?>&edit=<?=$x['id']?>">Edit</a><form method="post" onsubmit="return confirm('Delete this item?')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$x['id']?>"><button class="btn small danger">Delete</button></form><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="convert"><input type="hidden" name="id" value="<?=$x['id']?>"><button class="btn small secondary">→ <?=$isCat?'Tag':'Category'?></button></form></div></td></tr><?php endforeach; if(!$items):?><tr><td colspan="5">No items found.</td></tr><?php endif;?></tbody></table></div></section></div>
